import { SITE_TITLE, titled, WORDMARK } from "./brand";
import { PAGE_COLOR_RGB } from "./pwa-colors";

/** `--color-page` as the hex string the manifest and `themeColor` want (no literal, no fs read). */
export const PAGE_COLOR = `#${PAGE_COLOR_RGB.map((c) => c.toString(16).padStart(2, "0")).join("")}`;

/** Square, opaque, well over Google's 112px minimum: also the Organization `logo` in JSON-LD. */
export const LOGO_ICON = {
  src: "/icons/icon-512.png",
  sizes: "512x512",
  type: "image/png",
  purpose: "any",
} as const;

/** Generated by `scripts/generate-pwa-icons.mjs`; see `public/icons/README.md`. */
export const PWA_ICONS = [
  { src: "/icons/icon-192.png", sizes: "192x192", type: "image/png", purpose: "any" },
  LOGO_ICON,
  { src: "/icons/icon-maskable-512.png", sizes: "512x512", type: "image/png", purpose: "maskable" },
] as const;

export const PWA_NAMES = { name: titled(SITE_TITLE), shortName: WORDMARK } as const;
